import json
import datetime

# >>> practice-clock (canonical copy: scripts/practice-manager-kit/practice_clock.py; every copy must match it)
# Scheduled runs fire on a UTC clock; each practice decides from its own settings
# file ("timezone") whether this run is one of its own. Manual and event runs
# always count, so a person can still run an automation by hand at any time.
import datetime as _pm_datetime
from zoneinfo import ZoneInfo as _PmZoneInfo

PRACTICE_DEFAULT_TIMEZONE = "Australia/Sydney"
PRACTICE_SLOT_MINUTES = 30


def practice_clock_tz(practice):
    name = str((practice or {}).get("timezone") or "").strip() or PRACTICE_DEFAULT_TIMEZONE
    try:
        return _PmZoneInfo(name)
    except Exception:
        return _pm_datetime.timezone.utc


def practice_clock_now(practice, trig=None):
    # The run's scheduled time (not when the sandbox got to it), in the practice's time zone.
    fired = None
    if isinstance(trig, dict) and trig.get("fired_at"):
        try:
            fired = _pm_datetime.datetime.fromisoformat(str(trig.get("fired_at")).replace("Z", "+00:00"))
        except Exception:
            fired = None
    if fired is None or fired.tzinfo is None:
        fired = _pm_datetime.datetime.now(_pm_datetime.timezone.utc)
    return fired.astimezone(practice_clock_tz(practice))


def practice_open_now(practice, trig, start_hour, end_hour, weekdays=None):
    # True when a scheduled run falls inside [start_hour, end_hour) practice time
    # (weekdays: ISO numbers, 1 = Monday).
    if not (isinstance(trig, dict) and trig.get("kind") == "schedule"):
        return True
    local = practice_clock_now(practice, trig)
    if weekdays and local.isoweekday() not in weekdays:
        return False
    return start_hour <= local.hour < end_hour


def practice_due_at(practice, trig, hhmm, weekdays=None):
    # True for the one scheduled run that is the practice's own HH:MM run: the
    # first tick at or after HH:MM practice time (ticks are 30 minutes apart, so
    # a time zone with a :45 offset runs 15 minutes late rather than never).
    if not (isinstance(trig, dict) and trig.get("kind") == "schedule"):
        return True
    local = practice_clock_now(practice, trig)
    if weekdays and local.isoweekday() not in weekdays:
        return False
    hour, minute = (int(x) for x in str(hhmm).split(":"))
    target = hour * 60 + minute
    return target <= local.hour * 60 + local.minute < target + PRACTICE_SLOT_MINUTES
# <<< practice-clock


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def audit(slug, action, target, summary, workq_item_id=None):
    if not slug:
        return
    today = datetime.datetime.utcnow().strftime("%Y-%m-%d")
    path = "PracticeManager/AuditLog/" + slug + "-" + today + ".jsonl"
    try:
        existing = api.files.read(file=path)
    except Exception:
        existing = ""
    entry = {
        "ts": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
        "practice_slug": slug,
        "actor": "agent",
        "source": "automation:Form-chase reminder",
        "action": action,
        "target": target,
        "summary": summary,
    }
    if workq_item_id:
        entry["workq_item_id"] = workq_item_id
    line = json.dumps(entry, sort_keys=True)
    api.files.put(file=path, content=(existing + line + "\n") if existing else (line + "\n"))


entries = []
try:
    entries = api.files.list(path="PracticeManager/EnquiryThreads", scope="org")
except Exception:
    entries = []

practices_by_slug = {}


def practice_for(slug):
    if slug not in practices_by_slug:
        practices_by_slug[slug] = (read_json("PracticeManager/Practices/" + slug + ".json", {}) or {}) if slug else {}
    return practices_by_slug[slug]


chased = 0
checked = 0
for entry in entries or []:
    fname = entry.get("name") if isinstance(entry, dict) else entry
    if not fname or not str(fname).endswith(".json"):
        continue
    todo_id = str(fname)[:-5]
    thread = read_json("PracticeManager/EnquiryThreads/" + fname, {}) or {}
    if not thread or thread.get("status") != "booked":
        continue
    if thread.get("form_complete") or thread.get("form_chased"):
        # Never chase the same patient twice, and never chase once the form is known complete.
        continue
    # Runs every 30 minutes (UTC); each practice's patients are chased on its 7 AM run,
    # for appointments on its own tomorrow (its settings file's time zone).
    practice = practice_for(str(thread.get("slug") or ""))
    if not practice_due_at(practice, trigger, "07:00"):
        continue
    local_now = practice_clock_now(practice, trigger)
    tomorrow = (local_now + datetime.timedelta(days=1)).date()
    starts_at = str(thread.get("appointment_starts_at") or "")
    try:
        starts_local = datetime.datetime.fromisoformat(starts_at.replace("Z", "+00:00")).astimezone(local_now.tzinfo)
    except Exception:
        continue
    if starts_local.date() != tomorrow:
        continue
    patient_form_id = thread.get("patient_form_id") or ""
    if not patient_form_id:
        continue

    checked += 1
    try:
        pf = api.connectors.invoke(server="cliniko-clinical", tool="get_patient_form", args={"id": patient_form_id})
    except Exception:
        pf = None
    pf = pf if isinstance(pf, dict) else {}
    completed_at = pf.get("completed_at")
    form_url = str(pf.get("url") or "")

    if completed_at:
        thread["form_complete"] = True
        write_json("PracticeManager/EnquiryThreads/" + fname, thread)
        continue

    enquirer_email = thread.get("enquirer_email") or ""
    enquirer_name = thread.get("enquirer_name") or "there"
    if enquirer_email:
        body = (
            "Hi " + enquirer_name + ", just a reminder that your appointment is tomorrow (" + starts_at + "). "
            + ("Please complete your intake form before your visit: " + form_url if form_url else "Please complete your intake form before your visit.")
        )
        try:
            api.connectors.invoke(
                server="m365-mail-send", tool="send_email",
                args={"to": [enquirer_email], "subject": "Reminder: please complete your intake form", "body": body, "contentType": "Text"},
            )
            thread["form_chased"] = True
            write_json("PracticeManager/EnquiryThreads/" + fname, thread)
            audit(thread.get("slug") or "", "sent", {"kind": "email", "id": enquirer_email}, "Chased " + enquirer_name + " for an incomplete intake form", todo_id)
            chased += 1
        except Exception:
            pass

checked_count = checked
chased_count = chased
